BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(17);
SELECT ok(EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid='app_private.admission_student_handoffs'::regclass AND attname='destination_intent_id' AND attnotnull AND NOT attisdropped),'P39 Grade destination source id is required');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_identity_resolutions'::regclass AND conname='db03_handoff_identity_source_key' AND contype='u' AND cardinality(conkey)=3),'identity Person/application composite parent key');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_fee_dispositions'::regclass AND conname='db03_handoff_fee_source_key' AND contype='u' AND cardinality(conkey)=2),'fee decision/application composite parent key');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_destination_intents'::regclass AND conname='db03_handoff_grade_source_key' AND contype='u' AND cardinality(conkey)=3),'Grade/application composite parent key');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_identity_same_application' AND contype='f' AND confrelid='app_private.admission_identity_resolutions'::regclass AND cardinality(conkey)=3 AND cardinality(confkey)=3),'handoff identity and Person same application FK');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_fee_same_application' AND contype='f' AND confrelid='app_private.admission_fee_dispositions'::regclass AND cardinality(conkey)=2 AND cardinality(confkey)=2),'handoff fee declaration belongs to application');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_grade_same_application' AND contype='f' AND confrelid='app_private.admission_destination_intents'::regclass AND cardinality(conkey)=3 AND cardinality(confkey)=3),'handoff Grade comes from application destination history');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND contype='f' AND confrelid='app_private.admission_document_forwards'::regclass AND cardinality(conkey)=2),'preexisting same-application Forward FK retained');
SELECT ok((SELECT count(*)>=11 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND contype='f'),'all typed Person, Student, fee, Grade, Forward and receipt links remain');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND contype='u' AND cardinality(conkey)=1 AND conkey[1]=(SELECT attnum FROM pg_attribute WHERE attrelid='app_private.admission_student_handoffs'::regclass AND attname='application_id')),'exactly one approved handoff per application remains');
SELECT ok((SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid='app_private.admission_student_handoffs'::regclass),'RLS still enabled and forced');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgrelid='app_private.admission_student_handoffs'::regclass AND tgname='db03_handoff_mutation_disabled' AND NOT tgisinternal),'all handoff writes still prohibited');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgrelid='app_private.admission_student_handoffs'::regclass AND tgname='db03_handoff_no_truncate' AND NOT tgisinternal),'handoff TRUNCATE still prohibited');
SELECT ok(NOT has_table_privilege('authenticated','app_private.admission_student_handoffs','INSERT') AND NOT has_table_privilege('service_role','app_private.admission_student_handoffs','INSERT'),'no client/service-role handoff mutation grants');
SELECT ok(NOT has_table_privilege('schoolos_student_executor','app_private.admission_student_handoffs','INSERT') AND NOT has_table_privilege('schoolos_workflow_executor','app_private.admission_student_handoffs','INSERT'),'neither D1 nor Admissions can forge a handoff');
SELECT throws_ok($q$INSERT INTO app_private.admission_student_handoffs DEFAULT VALUES$q$,'P0001','DB03 atomic Student handoff writer unavailable','future schema cannot be fabricated into a handoff');
SELECT ok(to_regprocedure('app.approve_admission_principal(uuid,bigint,uuid,uuid)') IS NULL,'no Principal APPROVE command activated by P39');
SELECT * FROM finish();
ROLLBACK;
